// Экран «חוקי זיהוי» (איש מקצוע) в приложении. Вход — аккаунт эксперта jleprog34 (приложение залогинено вручную, запуск с BANCI_ACCOUNT=jleprog34).
// ОСТОРОЖНО: сохранение правил действует на ВСЕ семьи. Все тесты, кроме помеченных @data, правила НЕ сохраняют.
import { by, assert, skip } from './appium.mjs';
import { onHome, openTab } from './banci.mjs';

export const EXPERT_ACCOUNT = 'jleprog34';
export const FIELD_TYPES = '(type == "XCUIElementTypeTextField" OR type == "XCUIElementTypeTextView")';

/** Без аккаунта эксперта экран закрыт («המסך הזה פתוח רק לאיש המקצוע») — тест пропускается. */
export function requireExpert() {
  if (process.env.BANCI_ACCOUNT !== EXPERT_ACCOUNT) {
    skip(`нужен аккаунт эксперта ${EXPERT_ACCOUNT}: войти в приложение вручную и запустить с BANCI_ACCOUNT=${EXPERT_ACCOUNT}`);
  }
}

/** «חשבון» → «חוקי זיהוי» → экран загрузился (есть «גרסה נוכחית»). */
export async function openExpert(app) {
  await onHome(app);
  await openTab(app, 'חשבון');
  const row = await app.scrollTo(by.begins('חוקי זיהוי'), { what: 'строка «חוקי זיהוי» в «חשבון» (аккаунт не эксперт?)' });
  await row.click();
  await app.waitFor(by.contains('גרסה נוכחית'), { timeout: 20000, what: '«גרסה נוכחית» на экране «חוקי זיהוי»' });
}

/** Поле ввода под подписью: ближайшее TextField/TextView ниже подписи (прокрутка до подписи). */
export async function fieldBelow(app, label) {
  const lab = await app.scrollTo(by.exact(label), { what: `подпись «${label}»` });
  const labRect = await lab.rect();
  const fields = await app.findAll(FIELD_TYPES);
  assert(fields.length, `под «${label}» есть поле ввода`);
  const rects = await Promise.all(fields.map((f) => f.rect()));
  let best = null;
  rects.forEach((r, i) => {
    if (r.y + r.height >= labRect.y && (!best || r.y < best.r.y)) best = { el: fields[i], r };
  });
  assert(best, `под подписью «${label}» найдено поле ввода`);
  return best.el;
}

/** Убрать фокус с поля (клавиатура закрывается, значение фиксируется): тап по подписи экрана. */
export async function blur(app, label) {
  await app.tap(by.exact(label), { what: `подпись «${label}» (убрать фокус)` });
}

export const value = async (el) => String((await el.attr('value')) ?? '');

/** Клавиша экранной клавиатуры iOS по имени («,», «.», «0», «delete»). */
export const key = (name) => by.exact(name, 'Key');

/** Очистить поле нажатиями «delete» (поле должно быть в фокусе, клавиатура открыта). */
export async function clearFocused(app, el) {
  const n = (await value(el)).length + 3;
  for (let i = 0; i < n; i++) await app.tap(key('delete'), { what: 'клавиша «delete»' });
}

/** Закрыть клавиатуру многострочного поля (нет кнопки «Готово»): hideKeyboard, иначе тап по подписи. */
export async function hideKeyboard(app, label) {
  try { await app.exec('mobile: hideKeyboard', {}); } catch { await blur(app, label); }
}

/**
 * RTL по пикселям (#7581cb): в области элемента каждая строка текста прижата вправо — отступ чернил от правого края
 * меньше отступа от левого. Короткая строка в LTR-абзаце прижата влево, в RTL — вправо. Возвращает строки.
 */
export async function assertTextRtl(app, el, what, { minLines = 1 } = {}) {
  const { inkLines } = await import('./pixels.mjs');
  const { width: W } = await app.windowRect();
  const rect = await el.rect();
  const png = await app.screenshot(`rtl-${what.replace(/[^\w֐-׿]+/g, '-').slice(0, 40)}`);
  const lines = await inkLines(png, rect, W);
  assert(lines.length >= minLines, `${what}: на скриншоте найдено строк текста ≥ ${minLines} (найдено ${lines.length}; rect ${JSON.stringify(rect)}, скриншот ${png})`);
  lines.forEach((ln, i) => {
    assert(ln.rightGap < ln.leftGap, `${what}, строка ${i + 1}: прижата вправо (RTL) — отступ справа ${Math.round(ln.rightGap)} pt < слева ${Math.round(ln.leftGap)} pt (скриншот ${png})`);
  });
  return lines;
}
